const weekly = $json[0] || [];
const topWorkflows = $json[1] || [];
const mtd = $json[2] || [];
const wow = $json[3] || [];

let thisWeek = wow[0]?.week_cost || 0;
let lastWeek = wow[1]?.week_cost || 0;
let wowPct = lastWeek > 0 ? ((thisWeek - lastWeek) / lastWeek) * 100 : 0;

let totalWeekly = weekly.reduce((sum, r) => sum + parseFloat(r.total_cost_usd || 0), 0);
let totalMtd = mtd.reduce((sum, r) => sum + parseFloat(r.total_cost_usd || 0), 0);

let weeklyLines = weekly.slice(0, 7).map(r => 
  `  ${r.cost_date}: $${parseFloat(r.total_cost_usd).toFixed(4)} (${r.provider}/${r.model}, ${r.call_count} calls)`
).join('\n') || '  No data';

let topWfLines = topWorkflows.slice(0, 5).map(r => 
  `  ${r.workflow_name}: $${parseFloat(r.total_cost_usd).toFixed(4)} (${r.call_count} calls)`
).join('\n') || '  No data';

let mtdLines = mtd.map(r => 
  `  ${r.provider}/${r.model}: $${parseFloat(r.total_cost_usd).toFixed(4)} (${r.call_count} calls)`
).join('\n') || '  No data';

let wowArrow = wowPct >= 0 ? '📈' : '📉';

return [{
  json: {
    weekly_total: totalWeekly,
    mtd_total: totalMtd,
    this_week: thisWeek,
    last_week: lastWeek,
    wow_pct: wowPct,
    report_text: `📊 *Weekly LLM Cost Report* (${$now.format('YYYY-MM-DD')})

*Week Total:* $${totalWeekly.toFixed(4)}
*Month-to-Date:* $${totalMtd.toFixed(4)}
*WoW:* ${wowArrow} ${wowPct >= 0 ? '+' : ''}${wowPct.toFixed(1)}% (This: $${thisWeek.toFixed(4)}, Last: $${lastWeek.toFixed(4)})

*Daily Breakdown (Last 7 Days):*\n${weeklyLines}

*Top Workflows (All Time):*\n${topWfLines}

*MTD by Model:*\n${mtdLines}`
  }
}];
